import sys
import time

def even_parity(byte):
    # Calculate the even parity bit for the 8 data bits
    parity = 0
    for i in range(8):
        parity ^= (byte >> i) & 1
    # Even parity: so parity bit is 1 if number of 1s in byte is odd
    return parity ^ 1

def make_frame(byte):
    # 8-1-1 even parity: 8 data, 1 parity (as MSB)
    parity_bit = even_parity(byte)
    # Compose frame: parity as bit 8, data as bits 0-7 (MSB first: pbbbbbbbb)
    framed = (parity_bit << 8) | byte
    return framed.to_bytes(2, 'big')

def hexdump(data):
    for i in range(0, len(data), 16):
        chunk = data[i:i+16]
        hexstr = ' '.join(f'{b:02x}' for b in chunk)
        chars = ''.join(chr(b) if 32 <= b < 127 else '.' for b in chunk)
        print(f'{i:08x}  {hexstr:<47}  |{chars}|')

def main():
    # Try an initial byte: ASCII 'A' (0x41)
    test_byte = ord('A')
    frame = make_frame(test_byte)
    print(f"Sending frame for 'A': {frame.hex()}", file=sys.stderr)
    sys.stdout.buffer.write(frame)
    sys.stdout.flush()
    try:
        resp = sys.stdin.buffer.read(1)
        if resp:
            print('Response:', file=sys.stderr)
            hexdump(resp)
        else:
            print('No response received.', file=sys.stderr)
    except Exception as e:
        print(f'Exception: {e}', file=sys.stderr)

if __name__ == '__main__':
    main()

import sys
import time
from collections import deque

def even_parity(byte):
    # Counts parity bit: even parity (1 if odd number of 1's in byte)
    parity = 0
    for i in range(8):
        parity ^= (byte >> i) & 1
    # Even parity: parity bit is 1 if number of 1s in byte is odd
    return parity ^ 1

def make_frame(byte):
    # 8-1-1 even parity: 8 data, 1 parity (as MSB), 1 stop not encoded (transmitted otherwise)
    parity_bit = even_parity(byte)
    # Frame: parity (bit 8), data (bits 0-7)
    framed = (parity_bit << 8) | byte
    return framed.to_bytes(2, 'big')

def send_and_await_response(send_byte):
    frame = make_frame(send_byte)
    sys.stdout.buffer.write(frame)
    sys.stdout.flush()
    try:
        resp = sys.stdin.buffer.read(1)
        if not resp:
            return None
        return resp
    except Exception:
        return None

def try_flag_bytes():
    # Systematically send all ASCII and printable values to look for any flag-like output
    seen = set()
    for b in range(32, 128): # printable range
        response = send_and_await_response(b)
        if response == b'1':
            continue # Correct
        elif response == b'0':
            continue # Retransmit (let's skip for now)
        elif response and b'flag' in response:
            sys.stderr.write(f'Flag response: {response}\n')
            sys.stderr.flush()
        # Print all nontrivial responses
        if response not in (b'1', b'0', None) and response not in seen:
            sys.stderr.write(f'Interesting resp for {b}: {response}\n')
            sys.stderr.flush()
            seen.add(response)

def main():
    for b in b'flag{':
        response = send_and_await_response(b)
        time.sleep(0.05)
        if response not in (b'1', b'0', b''):
            sys.stderr.write(f'Resp: {response}\n')
            sys.stderr.flush()
    # Try all bytes in case
    try_flag_bytes()

if __name__ == '__main__':
    main()

import sys
import time

def even_parity(byte):
    parity = 0
    for i in range(8):
        parity ^= (byte >> i) & 1
    return parity ^ 1

def make_frame(byte):
    parity_bit = even_parity(byte)
    framed = (parity_bit << 8) | byte
    return framed.to_bytes(2, 'big')

def get_response():
    resp = sys.stdin.buffer.read(1)
    if not resp:
        return b''
    return resp

def main():
    flag = b''
    charset = b'flag{}_0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'
    for _ in range(60):
        found = False
        for c in charset:
            frame = make_frame(c)
            sys.stdout.buffer.write(frame)
            sys.stdout.flush()
            resp = get_response()
            if resp == b'1':
                flag += bytes([c])
                sys.stderr.write(f'Building: {flag!r}\n')
                sys.stderr.flush()
                found = True
                break
            elif resp == b'0':
                continue
            elif resp and b'flag' in resp:
                sys.stderr.write(f'Flag response!: {resp}\n')
                sys.stderr.flush()
        if not found:
            break
    sys.stderr.write(f'Final flag: {flag.decode(errors="ignore")}\n')
    sys.stderr.flush()

if __name__ == '__main__':
    main()

